const b = $json.body || $json;
const BASE = 'https://127.0.0.1:27124';
const enc = p => '/' + p.split('/').filter(Boolean).map(encodeURIComponent).join('/');
const a = (b.action || 'status').toLowerCase();
let method='GET', url=BASE+'/', body, qs, extraHeaders={};
const P = b.path ? enc(b.path) : '';
switch (a) {
  case 'status': break;
  case 'list': url = BASE + '/vault' + (b.dir ? enc(b.dir) + '/' : '/'); break;
  case 'read': url = BASE + '/vault' + P; break;
  case 'write': method='PUT'; url = BASE + '/vault' + P; body = b.content ?? ''; break;
  case 'append': method='POST'; url = BASE + '/vault' + P; body = b.content ?? ''; break;
  case 'delete': method='DELETE'; url = BASE + '/vault' + P; break;
  case 'patch':
    method='PATCH'; url = BASE + '/vault' + P;
    extraHeaders['Operation']=b.operation||'append';
    extraHeaders['Target-Type']=b.targetType||'heading';
    extraHeaders['Target']=b.target||'';
    body = b.content ?? '';
    break;
  case 'search': method='POST'; url = BASE + '/search/simple/'; qs = { query: b.query||'', contextLength: b.contextLength||100 }; break;
  case 'search-json': method='POST'; url = BASE + '/search/'; body = b.query||{}; break;
  case 'commands': url = BASE + '/commands/'; break;
  case 'command': method='POST'; url = BASE + '/commands/' + encodeURIComponent(b.command||''); break;
  case 'active': url = BASE + '/active/'; break;
  case 'open': method='POST'; url = BASE + '/open' + P; break;
  case 'periodic': method=b.method||'GET'; url = BASE + '/periodic/' + (b.period||'daily') + '/'; body = b.content; break;
  default: throw new Error('action inconnue: '+a);
}
return [{ json: { action:a, method, url, qs, body, extraHeaders } }];
